-- =============================================================================
-- Script   : 01_insert_actividades_economicas_ciiu.sql
-- Proposito: Poblar la BD de parametros con las Actividades Economicas (CIIU)
--            adoptadas por la DIAN: 502 clases CIIU Rev. 4 A.C. + 5 codigos
--            propios de la DIAN (0010, 0020, 0081, 0082, 0090) = 507 registros.
-- Esquema  : parametros
-- Tablas   : area_tipo -> tipo_parametro -> parametro  (orden obligatorio por FK)
-- Motor    : PostgreSQL
-- Idempotente: SI. Se puede ejecutar varias veces sin duplicar registros
--              (la llave natural del parametro es codigo_abreviacion).
-- Supuesto : las columnas "id" tienen secuencia/serial (autoincremental).
-- Fuente   : Resolucion DIAN 000114 de 2020 (compilacion DIAN) y resoluciones
--            modificatorias 1232/2022 y 86/2023.
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 1. AREA_TIPO  (1 registro; se omite si el area ya existe)
-- -----------------------------------------------------------------------------
INSERT INTO parametros.area_tipo
    (nombre, descripcion, codigo_abreviacion, activo, numero_orden,
     fecha_creacion, fecha_modificacion)
SELECT 'Información Tributaria',
       'Clasificaciones y catalogos de informacion tributaria',
       'IT',
       TRUE,
       COALESCE((SELECT MAX(numero_orden) FROM parametros.area_tipo), 0) + 1,
       CURRENT_TIMESTAMP,
       CURRENT_TIMESTAMP
WHERE NOT EXISTS (
    SELECT 1
    FROM parametros.area_tipo
    WHERE nombre = 'Información Tributaria'
);

-- -----------------------------------------------------------------------------
-- 2. TIPO_PARAMETRO  (1 registro, asociado al area_tipo anterior)
--    numero_orden = siguiente disponible dentro del area
-- -----------------------------------------------------------------------------
INSERT INTO parametros.tipo_parametro
    (nombre, descripcion, codigo_abreviacion, activo, numero_orden,
     fecha_creacion, fecha_modificacion, area_tipo_id)
SELECT 'Actividades Económicas (CIIU)',
       'Actividades economicas CIIU Rev. 4 A.C. adoptadas por la DIAN (RUT)',
       'CIIU',
       TRUE,
       COALESCE((SELECT MAX(tp.numero_orden)
                 FROM parametros.tipo_parametro tp
                 WHERE tp.area_tipo_id = a.id), 0) + 1,
       CURRENT_TIMESTAMP,
       CURRENT_TIMESTAMP,
       a.id
FROM parametros.area_tipo a
WHERE a.nombre = 'Información Tributaria'
  AND NOT EXISTS (
      SELECT 1
      FROM parametros.tipo_parametro t
      WHERE t.nombre = 'Actividades Económicas (CIIU)'
        AND t.area_tipo_id = a.id
  );

-- -----------------------------------------------------------------------------
-- 3. PARAMETRO  (507 registros, asociados al tipo_parametro anterior)
--    codigo_abreviacion = codigo de la actividad (texto de 4 digitos; conserva
--                         los ceros a la izquierda, p. ej. '0111')
--    nombre             = titulo de la actividad (max. 100 caracteres)
--    descripcion        = seccion, division y grupo CIIU de la actividad
--    numero_orden       = orden ascendente por codigo (1 a 507)
--    parametro_padre_id = NULL (catalogo plano)
-- -----------------------------------------------------------------------------
INSERT INTO parametros.parametro
    (nombre, descripcion, codigo_abreviacion, activo, numero_orden,
     fecha_creacion, fecha_modificacion, tipo_parametro_id, parametro_padre_id)
SELECT v.nombre,
       v.descripcion,
       v.codigo_abreviacion,
       TRUE,
       v.numero_orden,
       CURRENT_TIMESTAMP,
       CURRENT_TIMESTAMP,
       t.id,
       NULL
FROM (VALUES
    ('0010', 'Asalariados', 'Otras clasificaciones DIAN - Ingresos de relación laboral, legal o reglamentaria', 1),
